}

impl<S: Fallible + ?Sized> Serialize<S> for GodotEnum {
    fn serialize(&self, _serializer: &mut S) -> Result<Self::Resolver, S::Error> {
        Ok(())
    }
}

impl<D: Fallible + ?Sized> Deserialize<i32, D> for GodotEnum {
